#[doc = "The bivectors of PoincarÃ© motions: rotations `e23, e31, e12`, boosts `e41, e42, e43` and translations `e1i, e2i, e3i, e4i`."]
///
/// Blades, in coefficient order: `[e23, e31, e12, e41, e42, e43, e1i, e2i, e3i, e4i]`.
///
/// `S` lists the open slots: `Twist` (that is, `Twist<()>`) is a value, `Twist<(A,)>` a
/// linear map from `A`, `Twist<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Twist<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 10],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Twist<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Twist<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Twist<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Twist<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Twist");
        for (b, c) in <Twist as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Twist {
    const N: usize = 10;
    const NAME: &'static str = "Twist";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e23", "e31", "e12", "e41", "e42", "e43", "e1i", "e2i", "e3i", "e4i"];
    type Arr<X: gx::Elem> = [X; 10];
    type Mv<S: gx::Slots, T: gx::Coef> = Twist<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 10] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 10], mut f: impl FnMut(&X) -> Y) -> [Y; 10] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 10],
        b: &[Y; 10],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 10] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9])]
    }
}

