        let t57 = x[5] * s0;
        let t60 = x[5] * t31;
        let t63 = x[3] * t39;
        let t68 = x[4] * t23;
        let t71 = x[1] * t31;
        let t73 = x[9] * s0;
        let t75 = x[8] * t44;
        let t79 = x[6] * t45;
        let t81 = x[7] * t43;
        let t84 = x[7] * t41;
        let t87 = x[4] * t41;
        let t89 = t47 * T::from_i64(2);
        let t90 = x[0].mul_add(s0, t89);
        let t91 = t49 * T::from_i64(2);
        let t92 = x[1].mul_add(s0, t91);
        let t93 = t51 * T::from_i64(2);
        let t94 = x[2].mul_add(s0, t93);
        let t96 = (-t52).mul_add(T::from_i64(2), t53);
        let t98 = (-t54).mul_add(T::from_i64(2), t55);
        let t100 = (-t56).mul_add(T::from_i64(2), t57);
        let t101 = (-x[0]).mul_add(t15, t60);
        let t102 = (-x[4]).mul_add(t39, t101);
        let t103 = t102 * T::from_i64(2);
        let t104 = x[6].mul_add(s0, t103);
        let t105 = (-x[1]).mul_add(t15, t63);
        let t106 = (-x[5]).mul_add(t23, t105);
