        let t111 = t110 * T::from_i64(2);
        let t112 = x[8].mul_add(s0, t111);
        let t113 = x[0].mul_add(t23, t71);
        let t114 = x[2].mul_add(t39, t113);
        let t116 = (-t114).mul_add(T::from_i64(2), t73);
        let t117 = x[9].mul_add(t40, t75);
        let t118 = (-x[7]).mul_add(t45, t117);
