#[doc = "A bivector: the generator of a conformal transformation."]
///
/// Blades, in coefficient order: `[e23, e31, e12, e41, e42, e43, e1o, e2o, e3o, e4o, e1i, e2i, e3i, e4i, eoi]`.
///
/// `S` lists the open slots: `Bivector` (that is, `Bivector<()>`) is a value, `Bivector<(A,)>` a
/// linear map from `A`, `Bivector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Bivector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 15],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Bivector<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Bivector<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Bivector<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Bivector<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Bivector");
        for (b, c) in <Bivector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Bivector {
    const N: usize = 15;
    const NAME: &'static str = "Bivector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e23", "e31", "e12", "e41", "e42", "e43", "e1o", "e2o", "e3o", "e4o", "e1i", "e2i", "e3i", "e4i", "eoi"];
    type Arr<X: gx::Elem> = [X; 15];
    type Mv<S: gx::Slots, T: gx::Coef> = Bivector<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 15] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7), f(8), f(9), f(10), f(11), f(12), f(13), f(14)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 15], mut f: impl FnMut(&X) -> Y) -> [Y; 15] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7]), f(&a[8]), f(&a[9]), f(&a[10]), f(&a[11]), f(&a[12]), f(&a[13]), f(&a[14])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 15],
        b: &[Y; 15],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 15] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7]), f(&a[8], &b[8]), f(&a[9], &b[9]), f(&a[10], &b[10]), f(&a[11], &b[11]), f(&a[12], &b[12]), f(&a[13], &b[13]), f(&a[14], &b[14])]
    }
}

