    /// The identity map on `Quintvector`: a `Quintvector` with one open `Quintvector` slot.
    #[inline(always)]
    pub fn slot() -> Quintvector<(Quintvector,), T> {
        Quintvector { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `e234oi`.
